import { z } from 'zod';

/** UUID v7 string (time-sortable, generated by the database). */
export const uuid = z.string().uuid();
export type Uuid = z.infer<typeof uuid>;

/** ISO 8601 date-time, e.g. 2026-09-14T12:30:00.000Z. */
export const isoDateTime = z.string().datetime();
export type IsoDateTime = z.infer<typeof isoDateTime>;

/** Calendar date, YYYY-MM-DD. */
export const isoDate = z.string().date();
export type IsoDate = z.infer<typeof isoDate>;

/** Row audit columns, shared by every table (decisions.md: IDs and DB conventions). */
export const timestamps = z.object({
  createdAt: isoDateTime,
  updatedAt: isoDateTime,
});
export type Timestamps = z.infer<typeof timestamps>;

/** Required free text that cannot be empty or whitespace-only. */
export const nonEmptyString = z.string().trim().min(1);
export type NonEmptyString = z.infer<typeof nonEmptyString>;

/** Optional qualitative free text; 5000 is the storage ceiling, not a UI cap. */
export const optionalText = z.string().trim().max(5000).optional();
export type OptionalText = z.infer<typeof optionalText>;
